import math
from itertools import permutations

def is_square(k):
    if k < 1:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    # Check the total sum first. If it's a square, n is not cool.
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return False

    # Backtracking search for a valid permutation
    numbers = list(range(1, n + 1))

    def solve(current_path, current_sum, remaining_numbers):
        if len(current_path) == n:
            # Should have been caught by the total_sum check, but good practice
            return True

        for i in range(len(remaining_numbers)):
            next_number = remaining_numbers[i]
            next_sum = current_sum + next_number

            if not is_square(next_sum):
                # Recurse: use next_number
                new_path = current_path + [next_number]
                new_remaining = remaining_numbers[:i] + remaining_numbers[i+1:]

                if solve(new_path, next_sum, new_remaining):
                    return True

        return False

    # Start the search
    return solve([], 0, numbers)

# Test n from 1 to 15
results = {}
print("Testing n=1 to n=15:")
for n in range(1, 16):
    try:
        cool = is_cool(n)
        results[n] = cool
        print(f"n={n}: {'Cool' if cool else 'Not Cool'}")
    except RecursionError:
        # This might happen for larger n if the search depth is hit, 
        # but for n<=15 it should be fine.
        results[n] = False
        print(f"n={n}: Search failed (RecursionError)")

# Extract the cool integers
cool_integers = [n for n, is_c in results.items() if is_c]
print("\nList of cool integers up to 15:", cool_integers)
